(6837847, 1029073, 138253, '<td valign="top">Beautiful model, great positioning.<br/>the pose is confident and strong without being agressive.<br/>B&amp;W works great for this image (guessing Nik Silver Efex Pro?)</td>', 'Beautiful model, great positioning.the pose is confident and strong without being agressive.B&W works great for this image (guessing Nik Silver Efex Pro?)', '2012-08-08 11:33:38.000000', NULL, 1),
(6837848, 1028534, 138253, '<td valign="top">i''m very rarely a fan of this type of blur, but in this case it works great - it gives the feeling of being in one of the jets of water and trying to look through it, and that works perfectly with your title<br/>giving this an 8 where most times i''d have gone with a 4/5</td>', 'i''m very rarely a fan of this type of blur, but in this case it works great - it gives the feeling of being in one of the jets of water and trying to look through it, and that works perfectly with your titlegiving this an 8 where most times i''d have gone with a 4/5', '2012-08-08 11:35:24.000000', NULL, 1),
(6837851, 1028897, 138253, '<td valign="top">Man, God''s a bit of a pervert if he''s trying to watch us while we sleep ;)<br/>Nice capture though. :)</td>', 'Man, God''s a bit of a pervert if he''s trying to watch us while we sleep ;)Nice capture though. :)', '2012-08-08 11:36:53.000000', NULL, 1),
(6837852, 1028919, 23484, '<td valign="top">Wow, this is very cool. There is so much to see with the kids, the trees, and the boat.</td>', 'Wow, this is very cool. There is so much to see with the kids, the trees, and the boat.', '2012-08-08 11:37:33.000000', NULL, 1),
