INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6841631, 1028781, 96530, '<td valign="top">Congrats on the blue Lydia! You little monkey did a great job for you here ;)</td>', 'Congrats on the blue Lydia! You little monkey did a great job for you here ;)', '2012-08-15 01:11:19.000000', NULL, 0),
(6841634, 1028687, 96530, '<td valign="top">Ha! So are you glad I dragged you out into the heat now Johanna? So glad you bagged a very useful shot from the session and I had lots of fun being there shooting with you :)  Congrats!</td>', 'Ha! So are you glad I dragged you out into the heat now Johanna? So glad you bagged a very useful shot from the session and I had lots of fun being there shooting with you :)  Congrats!', '2012-08-15 01:13:47.000000', NULL, 0),
(6841635, 1028781, 83313, '<td valign="top">Ribit?</td>', 'Ribit?', '2012-08-15 01:14:00.000000', NULL, 0),
(6841637, 1028722, 112828, '<td valign="top">Nice one Spiff.</td>', 'Nice one Spiff.', '2012-08-15 01:17:30.000000', NULL, 0),
(6841639, 1028951, 138630, '<td valign="top">I was a 10 - sorry I did not have the time to comment on this challenge.  I am surprised and disappointed that this did not finish much higher.  The simile is, as PennyStreet, EntertainMe, and CrazyDiamond have stated, lovely and thought provoking.  You came up with a clever and effective way to illustrate it, and you executed it very well.  The image stands on its own - it should have done very well in this challenge.  Just my opinion, obviously :)</td>', 'I was a 10 - sorry I did not have the time to comment on this challenge.  I am surprised and disappointed that this did not finish much higher.  The simile is, as PennyStreet, EntertainMe, and CrazyDiamond have stated, lovely and thought provoking.  You came up with a clever and effective way to illustrate it, and you executed it very well.  The image stands on its own - it should have done very well in this challenge.  Just my opinion, obviously :)', '2012-08-15 01:18:26.000000', NULL, 0),
(6841647, 1029079, 69008, '<td valign="top">If the numbers are correct, the high iso and the very small aperture may have contributed much toward the softness of this one, which was mentioned by both you and one commenter.  Light coming through a tiny aperture becomes diffused as the aperture begins working somewhat like a pinhole lens as it becomes smaller and smaller. It''s just physics.  The best sharpness is between f5.6 and f11 for most lenses.  <br/>I also see the disruption of the diagonal shadow across the subject. With sleeping animals though, you can''t just rearrange things without losing the subject. <br/>You have a very good looking friend here, and I can see in your portfolio that he means a lot to you.</td>', 'If the numbers are correct, the high iso and the very small aperture may have contributed much toward the softness of this one, which was mentioned by both you and one commenter.  Light coming through a tiny aperture becomes diffused as the aperture begins working somewhat like a pinhole lens as it becomes smaller and smaller. It''s just physics.  The best sharpness is between f5.6 and f11 for most lenses.  I also see the disruption of the diagonal shadow across the subject. With sleeping animals though, you can''t just rearrange things without losing the subject. You have a very good looking friend here, and I can see in your portfolio that he means a lot to you.', '2012-08-15 01:31:32.000000', NULL, 0),
